using System;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;

public static class ContributorService
{
    public static async Task RenameContributorAsync(
        BlogContext context,
        int contributorId,
        string newName,
        CancellationToken cancellationToken = default)
    {
        var contributor = await context.Contributors.FindAsync(
            new object[] { contributorId },
            cancellationToken);

        if (contributor is null)
        {
            throw new InvalidOperationException($"Contributor with ID {contributorId} was not found.");
        }

        contributor.Name = newName;

        await context.SaveChangesAsync(cancellationToken);
    }
}
